// Ghi lại thứ tự bắt đầu/kết thúc để thấy "thác nước" (waterfall)
const events = [];
const delay = (ms, v) => new Promise((r) => setTimeout(() => r(v), ms));
const fetchUser = async () => { events.push("start user"); await delay(20); events.push("end user"); return "An"; };
const fetchPosts = async () => { events.push("start posts"); await delay(20); events.push("end posts"); return 3; };

(async () => {
  // TUẦN TỰ: posts chỉ bắt đầu sau khi user xong => chậm gấp đôi
  await fetchUser();
  await fetchPosts();
  console.log(events.join(","));
})();

