const events = [];
const delay = (ms) => new Promise((r) => setTimeout(r, ms));
const a = async () => { events.push("start A"); await delay(20); events.push("end A"); };
const b = async () => { events.push("start B"); await delay(20); events.push("end B"); };
(async () => {
  await Promise.all([a(), b()]);
  console.log(events.join(","));
