let real = 0;
function memo(fn) {
  const m = new Map();
  return (k) => {
    if (!m.has(k)) m.set(k, fn(k));
    return m.get(k);
  };
}
const get = memo((id) => { real++; return "user" + id; });
get("1"); get("1"); get("2");
console.log(real);
